foundation.question_text:
Let $H$ be the height, in centimetres, of a randomly chosen Year 12 student. Find $P(H = 170)$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.13cm, y=1cm]
\draw[->] (146,0) -- (194,0) node[right] {$x$};
\draw[->] (148,-0.5) -- (148,3.0) node[above] {$f(x)$};
\draw[thick, domain=150:190, smooth, samples=100, variable=\x] plot ({\x},{2.4*exp(-0.5*((\x-170)/5)*((\x-170)/5))});
\draw[dashed] (170,0) -- (170,2.4);
\draw (150,0) -- (150,-0.12) node[below] {$150$};
\draw (170,0) -- (170,-0.12) node[below] {$170$};
\draw (190,0) -- (190,-0.12) node[below] {$190$};
\end{tikzpicture}
[/tikz]

development.question_text:
A continuous random variable $X$ has $P(X < 3) = 0.15$ and $P(X < 8) = 0.62$. Find $P(3 \le X \le 8)$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=0.55cm, y=1cm]
\fill[gray!35, domain=3:8, variable=\x] (3,0) -- plot ({\x},{2.2*exp(-0.5*((\x-5.5)/2.2)*((\x-5.5)/2.2))}) -- (8,0) -- cycle;
\draw[->] (-0.6,0) -- (11.6,0) node[right] {$x$};
\draw[->] (0,-0.5) -- (0,2.9) node[above] {$f(x)$};
\draw[thick, domain=0:11, smooth, samples=100, variable=\x] plot ({\x},{2.2*exp(-0.5*((\x-5.5)/2.2)*((\x-5.5)/2.2))});
\draw (3,0) -- (3,1.153);
\draw (8,0) -- (8,1.153);
\node[below] at (3,0) {$3$};
\node[below] at (8,0) {$8$};
\end{tikzpicture}
[/tikz]

